/**
 * T4 — the runtime level model.
 *
 * Fed the JSON that `tools/decode-levels.ts` writes out of `/levels/J2MElvl.NNN`; it does
 * no I/O of its own, so tools, tests and the game all share one model. The MIDlet keeps
 * the same data in `b.F`, a `short[height][width]`, and mutates cells in place as the ball
 * collects things — `Level.tiles` is likewise mutable and `setTileAt()` is how gameplay
 * writes back.
 *
 * See docs/ORIGINAL.md for how each field was identified.
 */

/** Tile edge in pixels. 12, not 16 — `b.a(Image,int,int,int)` and `b.H` both say so. */
export const TILE_SIZE = 12;

/** Moving platforms are one 24x24 sprite (`b.Q`), i.e. two tiles square. */
export const PLATFORM_SIZE = 24;

/**
 * A tile byte is `id | flags`. `e.a(...)` switches on `F[y][x] & ~0x40 & ~0x80`, so the
 * low six bits are the tile id and the top two are flags.
 */
export const TILE_ID_MASK = 0x3f;

/**
 * Bit 6 — the cell is underwater. `b.a(int,int,int,int)` fills the cell with `#1060B0`
 * (deep blue) when it is set and `#B0E0F0` (pale sky) when it is not, and every
 * collectible keeps the bit when it rewrites its own cell (`0x91 | n3`).
 */
export const TILE_UNDERWATER = 0x40;

/**
 * Bit 7 — "repaint this cell", set at runtime and cleared by the tile drawer. No level
 * file uses it; the decoder rejects one that does.
 */
export const TILE_REDRAW = 0x80;

/** Tile ids named so far. The full id -> sprite/behaviour table is T7's job. */
export const EMPTY_TILE = 0;
export const SOLID_TILE = 1;
export const SOLID_TILE_ALT = 2;
export const DOOR_TILE = 9;

/**
 * The four hoop flavours. Each hoop is two tiles: `head` then `tail`, adjacent along
 * `axis`. `e.a(...)`'s cases 13/15 (and 21/23) are the head, 14/16 (22/24) the tail.
 * `small` hoops bail out on `this.a == 16`, so only a deflated ball fits through them.
 */
export const HOOPS = [
  { head: 13, tail: 14, axis: 'y', small: true },
  { head: 15, tail: 16, axis: 'x', small: true },
  { head: 21, tail: 22, axis: 'y', small: false },
  { head: 23, tail: 24, axis: 'x', small: false },
] as const satisfies readonly { head: number; tail: number; axis: 'x' | 'y'; small: boolean }[];

/** Ball diameters. Header byte 2 picks one; `e` toggles between them on inflate/deflate. */
export const BALL_SMALL = 12;
export const BALL_LARGE = 16;

export type PlatformJson = {
  /** Top-left tile of the box the platform travels inside (`b.U`). */
  x0: number;
  y0: number;
  /**
   * Bottom-right corner of that box (`b.T`), **exclusive**: the platform's travel is
   * `(x1 - x0 - 2) * 12`, so at full offset its far edge lands exactly on `x1 * 12`.
   * Level 7 has boxes whose `y1` equals the map height, which only parses if it is a
   * corner rather than a tile.
   */
  x1: number;
  y1: number;
  /** Pixels added to the offset each tick, sign-flipped at the ends (`b.am`). */
  speedX: number;
  speedY: number;
  /** Starting pixel offset inside the box (`b.z`). */
  offsetX: number;
  offsetY: number;
};

export type LevelJson = {
  /** 1-based, matching the `J2MElvl.NNN` suffix. */
  id: number;
  width: number;
  height: number;
  /** Tile the ball is placed in on entry (`b.v`, `b.Y`). */
  spawn: { x: number; y: number };
  /** Ball diameter on entry: 12 or 16 (`b.a`, from header byte 2). */
  startBallSize: number;
  /** Top-left tile of the 2x2 exit door (`b.ac`, `b.ab`). */
  door: { x: number; y: number };
  /** Hoops that must be collected before the door opens (`b.ay`). */
  hoopCount: number;
  /** `width * height` tile bytes, row-major. */
  tiles: number[];
  platforms: PlatformJson[];
};

/** A moving platform, with the travel range `b.l()` derives from its box. */
export class Platform {
  readonly rangeX: number;
  readonly rangeY: number;
  offsetX: number;
  offsetY: number;
  speedX: number;
  speedY: number;

  readonly json: PlatformJson;

  constructor(json: PlatformJson) {
    this.json = json;
    // b.l(): the offset is clamped to (T - U - 2) * 12 — the box, less the platform's own
    // two-tile footprint — and the speed flips sign at either end.
    this.rangeX = (json.x1 - json.x0 - 2) * TILE_SIZE;
    this.rangeY = (json.y1 - json.y0 - 2) * TILE_SIZE;
    this.offsetX = json.offsetX;
    this.offsetY = json.offsetY;
    this.speedX = json.speedX;
    this.speedY = json.speedY;
  }

  /** Pixel position of the top-left corner, as `e.a(...)`'s case 10 computes it. */
  get x(): number {
    return this.json.x0 * TILE_SIZE + this.offsetX;
  }

  get y(): number {
    return this.json.y0 * TILE_SIZE + this.offsetY;
  }
}

export class Level {
  readonly id: number;
  readonly width: number;
  readonly height: number;
  readonly spawn: { readonly x: number; readonly y: number };
  readonly startBallSize: number;
  readonly door: { readonly x: number; readonly y: number };
  readonly hoopCount: number;
  readonly platforms: readonly Platform[];
  /** Mutable, like `b.F`: collecting a hoop rewrites its two cells. */
  readonly tiles: number[];

  constructor(json: LevelJson) {
    if (json.tiles.length !== json.width * json.height) {
      throw new Error(
        `level ${json.id}: ${json.tiles.length} tiles for a ${json.width}x${json.height} map`,
      );
    }
    this.id = json.id;
    this.width = json.width;
    this.height = json.height;
    this.spawn = json.spawn;
    this.startBallSize = json.startBallSize;
    this.door = json.door;
    this.hoopCount = json.hoopCount;
    this.tiles = [...json.tiles];
    this.platforms = json.platforms.map((platform) => new Platform(platform));
  }

  get pixelWidth(): number {
    return this.width * TILE_SIZE;
  }

  get pixelHeight(): number {
    return this.height * TILE_SIZE;
  }

  contains(x: number, y: number): boolean {
    return x >= 0 && y >= 0 && x < this.width && y < this.height;
  }

  /**
   * The raw tile byte, id and flags.
   *
   * Out of bounds reads as solid. This is a deliberate deviation: `e` indexes `q.F[y][x]`
   * unguarded, so the original would throw, and the shipped maps are *not* walled in —
   * most have long stretches of empty tiles along an edge (level 8 has 268 of them). The
   * interior geometry is what keeps the ball in play there. Treating the outside as wall
   * keeps the collision code branch-free and fails soft if the ball ever gets out.
   */
  rawTileAt(x: number, y: number): number {
    if (!this.contains(x, y)) return SOLID_TILE;
    return this.tiles[y * this.width + x] ?? SOLID_TILE;
  }

  /** The tile id with the underwater/redraw flags stripped — what `e` switches on. */
  tileAt(x: number, y: number): number {
    return this.rawTileAt(x, y) & TILE_ID_MASK;
  }

  /** Tile id at a pixel position. */
  tileAtPixel(px: number, py: number): number {
    return this.tileAt(Math.floor(px / TILE_SIZE), Math.floor(py / TILE_SIZE));
  }

  isUnderwater(x: number, y: number): boolean {
    return (this.rawTileAt(x, y) & TILE_UNDERWATER) !== 0;
  }

  /**
   * Writes a cell byte verbatim, flags and all.
   *
   * T8 needs it because `e`'s crystal and crystal-ball cases write `128` and `136`
   * outright — id plus the redraw bit, with no `| (tile & 0x40)` — so they *lose* the
   * cell's underwater flag where every hoop write keeps it. That is the original's bug and
   * it is visible (the cell turns from water to sky), so the port reproduces it and this
   * is the door it goes through. Prefer `setTileAt()` anywhere the flag should survive.
   */
  setRawTileAt(x: number, y: number, raw: number): void {
    if (!this.contains(x, y)) return;
    this.tiles[y * this.width + x] = raw;
  }

  /** Writes a tile id, preserving the cell's underwater flag as the original does. */
  setTileAt(x: number, y: number, id: number): void {
    if (!this.contains(x, y)) return;
    const index = y * this.width + x;
    const raw = this.tiles[index] ?? 0;
    this.tiles[index] = (id & TILE_ID_MASK) | (raw & TILE_UNDERWATER);
  }

  /** How many times each tile id (flags stripped) occurs. */
  tileCounts(): Map<number, number> {
    const counts = new Map<number, number>();
    for (const tile of this.tiles) {
      const id = tile & TILE_ID_MASK;
      counts.set(id, (counts.get(id) ?? 0) + 1);
    }
    return counts;
  }

  /** Hoops present in the tilemap, counted by their head tile. Matches `hoopCount`. */
  countHoops(): number {
    const counts = this.tileCounts();
    return HOOPS.reduce((total, hoop) => total + (counts.get(hoop.head) ?? 0), 0);
  }
}

/**
 * PLAN.md §0.2's legend: `.` empty, `#` solid (ids 1 and 2), every other id a letter —
 * `A + (id - 1) % 26`, so id 3 prints `C` and id 9 prints `I`.
 *
 * Past id 26 the letters wrap and collide (29 also prints `C`), which is fine for
 * eyeballing a map's shape; use `Level.tileCounts()` when the exact id matters.
 */
export function tileGlyph(id: number): string {
  if (id === EMPTY_TILE) return '.';
  if (id === SOLID_TILE || id === SOLID_TILE_ALT) return '#';
  return String.fromCharCode(65 + ((id - 1) % 26));
}

/** Renders the tile layer as ASCII, one string per row. The project's main map debugger. */
export function toAscii(level: Level): string[] {
  const rows: string[] = [];
  for (let y = 0; y < level.height; y++) {
    let row = '';
    for (let x = 0; x < level.width; x++) row += tileGlyph(level.tileAt(x, y));
    rows.push(row);
  }
  return rows;
}
