/**
 * T7 — the tile id table: what every id draws and what it does.
 *
 * Two switches in the MIDlet define this, and both are transcribed here rather than
 * summarised:
 *
 * - `b.a(int col, int row, int px, int py)` — the tile drawer. It fills the cell with the
 *   sky/water colour, draws one image from `b.V` into the level buffer, and for the hoop
 *   ids hands a *second* image to `b.b(Image,int,int)`, a deferred list that `d.n()`
 *   flushes **after** the ball has been drawn. That is the whole of the two-layer scheme:
 *   the ball passes visually through a hoop because half the hoop is painted over it.
 * - `e.a(int row, int col, boolean)` — the collision/pickup switch, which is where the
 *   behaviour column comes from.
 *
 * Both switch on `F[y][x] & ~0x40 & ~0x80`, so an id is 0..63; 0..54 are used, and
 * 8, 11, 12, 17..20, 25..28, 48, 49 and 52 never appear in a level file (8 and the
 * collected-hoop ids are written at runtime; 11, 12, 48, 49 and 52 have no call site at
 * all). See docs/TILES.md for the table in prose and docs/ORIGINAL.md for the flag bits.
 */

/** `b.a(...)`'s `A.setColor(11591920)` — the above-water cell background. */
export const SKY_COLOUR = 0xb0e0f0;

/** `b.a(...)`'s `A.setColor(1073328)` — the underwater cell background. */
export const WATER_COLOUR = 0x1060b0;

/** `d.n()`'s `ad.fillRect(0, 97, 128, 32)` in `setColor(545706)` — the HUD strip. */
export const HUD_COLOUR = 0x0853aa;

/**
 * What a tile does when the ball reaches it. Names come from `e`'s method bodies —
 * `e.e()` is the death routine, `e.c()`/`e.f()` deflate and inflate, `e.d()` scores a
 * hoop — and from the mechanics the localization strings name (PLAN.md §0.3).
 */
export type TileKind =
  | 'empty'
  | 'solid'
  | 'rubber'
  | 'spike'
  | 'crystal'
  | 'checkpoint'
  | 'door'
  | 'hazard'
  | 'hoop'
  | 'hoop-collected'
  | 'crystal-ball'
  | 'deflator'
  | 'inflator'
  | 'gravity-flip'
  | 'speed-boost'
  | 'jump-boost'
  | 'unused';

export type TileSpec = {
  /** Atlas frame drawn into the level buffer, before the ball. */
  back?: string;
  /** Frame for the same cell when bit 6 (underwater) is set; `back` is used when absent. */
  backWater?: string;
  /**
   * Atlas frame handed to `b.b(Image,int,int)` — drawn *after* the ball, so the ball
   * disappears behind it. Only the hoop ids have one.
   */
  front?: string;
  /**
   * Quarter turns counter-clockwise applied to `back` at draw time. The MIDlet calls
   * `b.a(V[n], 3|4|5)` = `ROTATE_90|180|270` inline for these ids instead of caching the
   * result in `V`, so there is no pre-baked atlas frame to point at.
   */
  turns?: number;
  kind: TileKind;
  /** One line for docs/TILES.md, and for the debug overlay. */
  note: string;
};

/**
 * Indexed by tile id. A hole means the drawer has no `case` for it: the cell keeps its
 * background fill and nothing else.
 *
 * The hoop entries repay a second look. There are four flavours, each two cells, each
 * cell a back half and a front half:
 *
 * | flavour | uncollected | collected | axis | fits |
 * | --- | --- | --- | --- | --- |
 * | orange B | 13, 14 | 17, 18 | vertical | small ball only |
 * | orange B | 15, 16 | 19, 20 | horizontal | small ball only |
 * | orange A | 21, 22 | 25, 26 | vertical | either |
 * | orange A | 23, 24 | 27, 28 | horizontal | either |
 *
 * Collecting one rewrites both cells to `id + 4` (`e.a(...)`'s `0x91 | n3` … `0x9C | n3`,
 * keeping the underwater bit), and the collected form swaps the orange bar cell for the
 * grey one — same geometry, spent colour.
 */
// One tile id per line, indexed by the `/* n */` markers: wrapping the entries would
// turn a 55-row table anyone can scan into 250 lines nobody can.
// prettier-ignore
