/** The drawer's `case 9`: the door cell renders a window onto `b.ah`, not a tile sprite. */
export const DOOR_ID = 9;

/** The drawer's `case 10`: the cell renders whatever part of the hazard overlaps it. */
export const HAZARD_BOX_ID = 10;

export function tileSpec(id: number): TileSpec | undefined {
  return TILES[id];
}

/**
 * Cell background colour. `b.a(...)` sets it from bit 6 before the switch, except for the
 * hazard box, which hard-codes sky even underwater (`case 10`'s `setColor(11591920)`).
 */
export function cellColour(id: number, underwater: boolean): number {
  if (id === HAZARD_BOX_ID) return SKY_COLOUR;
  return underwater ? WATER_COLOUR : SKY_COLOUR;
}

/** Frame for a cell's back layer, picking the underwater variant when there is one. */
export function backFrame(id: number, underwater: boolean): string | undefined {
  const spec = TILES[id];
  if (!spec) return undefined;
  return underwater ? (spec.backWater ?? spec.back) : spec.back;
}
