/**
 * T7 — the exit door's opening animation, from `b.a(int,int,Image)`, `b.m()` and `b.g()`.
 *
 * The door is four tiles, ids `9`, at `(b.ac, b.ab)` — header bytes 3 and 4. Its artwork
 * is `V[12]`, a **24x48** strip that `b.b(Image)` paints once at load: a hand-drawn shaft
 * in the lower half, four mirrored copies of cell (2,3) forming the shut door in the
 * upper. `b.ah` is a 24x24 window onto that strip, and `b.m()` redraws it at `-c`. So the
 * door "opens" by sliding the shut panel up out of the window and the shaft in behind it.
 *
 * `b.g()` advances `c` by 4 and latches `b.R` — "the door is open" — at 24. It is called
 * from `d.a()` only while the door is on screen and every hoop has been collected
 * (`aa == ay`), so the animation is six ticks (240 ms) of visible sliding, not a timer
 * that runs while the player is elsewhere.
 */

/** `b.ah` — the window onto the strip, and the door's footprint: 2x2 tiles. */
export const DOOR_SIZE = 24;

/** `b.g()`'s `this.c += 4`. */
export const DOOR_OPEN_STEP = 4;

export class Door {
  /** `b.c` — pixels the panel has slid, 0 (shut) to 24 (open). */
  offset = 0;

  /** `b.R` — set once `offset` reaches 24; `e.a(...)`'s `case 9` needs it to let the ball through. */
  open = false;

  /** `b.a(int,int,Image)`'s `this.c = 0; this.R = false;` — called when a level loads. */
  reset(): void {
    this.offset = 0;
    this.open = false;
  }

  /** `b.g()`. Safe to call after the door is open; it stays open. */
  advance(): void {
    this.offset += DOOR_OPEN_STEP;
    if (this.offset >= DOOR_SIZE) {
      this.offset = DOOR_SIZE;
      this.open = true;
    }
  }
}
