/**
 * T7 — the moving hazards, ported from `b.l()`.
 *
 * The 8-byte records PLAN.md calls "moving platforms" are read into four `short[2]`s
 * (`b.U`, `b.T`, `b.am`, `b.z`) by `b.a(DataInputStream)` and stepped once per tick by
 * `b.l()`. `src/game/Level.ts` already models one as a travel box plus a speed and an
 * offset; this is the step, and it is deliberately a plain function over that model so a
 * test can run a few hundred ticks without a renderer.
 *
 * **They are hazards, not platforms.** PLAN.md T9's table says "collision + carrying the
 * ball"; `e.a(...)`'s `case 10` says otherwise — it tests the ball against the 24x24
 * sprite's rectangle and, on an overlap, calls `e.e()`, the same death routine the spikes
 * use. The artwork agrees: `b.Q` is cell (1,3) — a chain link — mirrored four ways into a
 * spiked wheel. Nothing anywhere sets the ball's position from a platform's.
 *
 * The step has one quirk worth keeping. The speed is clamped *and then* tested for
 * equality against either end, so a record whose range is zero or negative flips its speed
 * every single tick and never moves; three shipped records rely on that rather than being
 * rejected (level 3 #10, level 8 #1, level 9 #3 — see docs/ORIGINAL.md).
 */
import type { Level, Platform } from './Level.ts';
import { PLATFORM_SIZE } from './Level.ts';

/** One `b.l()` iteration for a single record. */
export function stepPlatform(platform: Platform): void {
  platform.offsetX += platform.speedX;
  if (platform.offsetX < 0) platform.offsetX = 0;
  else if (platform.offsetX > platform.rangeX) platform.offsetX = platform.rangeX;
  if (platform.offsetX === 0 || platform.offsetX === platform.rangeX) {
    platform.speedX = -platform.speedX;
  }

  platform.offsetY += platform.speedY;
  if (platform.offsetY < 0) platform.offsetY = 0;
  else if (platform.offsetY > platform.rangeY) platform.offsetY = platform.rangeY;
  if (platform.offsetY === 0 || platform.offsetY === platform.rangeY) {
    platform.speedY = -platform.speedY;
  }
}

/** `d.a()`'s `if (this.E != 0) this.l();` — every record, once per tick. */
export function stepPlatforms(level: Level): void {
  for (const platform of level.platforms) stepPlatform(platform);
}

/**
 * `b.b(int col, int row)` — the record whose travel box contains a cell, or none.
 *
 * A linear scan, as in the original, and `T` is read as the exclusive corner T7 settled
 * on. `e.a(...)`'s `case 10` calls this for every id-10 cell the ball's box covers, so it
 * runs a handful of times a tick against at most a dozen records; there is nothing to
 * index.
 */
export function hazardForCell(level: Level, col: number, row: number): Platform | undefined {
  return level.platforms.find(
    ({ json }) => json.x0 <= col && json.x1 > col && json.y0 <= row && json.y1 > row,
  );
}

/**
 * The rectangle `e.a(...)`'s `case 10` tests the ball against: the sprite's 24x24 box at
 * its current offset, inset by one pixel on the top-left as the original does
 * (`n6 + 1, n5 + 1, n6 + 24 - 1, n5 + 24 - 1`).
 */
export function hazardBounds(platform: Platform): {
  left: number;
  top: number;
  right: number;
  bottom: number;
} {
  return {
    left: platform.x + 1,
    top: platform.y + 1,
    right: platform.x + PLATFORM_SIZE - 1,
    bottom: platform.y + PLATFORM_SIZE - 1,
  };
}
