/**
 * T7 — the tile layer, replacing `b.H` and its drawer.
 *
 * The MIDlet paints tiles into a 156x96 offscreen `Image` and scrolls it as a ring
 * buffer, redrawing only the column that has just come into view and any cell flagged
 * dirty (`0x80`). That is a memory strategy for a handset with a few hundred kilobytes of
 * heap; on a GPU it buys nothing. This rebuilds the visible window — at most 12x9 cells —
 * from the tilemap every time the camera moves, out of a pool of sprites, and the
 * incremental machinery goes away with it.
 *
 * What does **not** go away is the layering, which is load-bearing for how the game
 * looks. `b.a(...)` draws each cell in three passes:
 *
 *   1. a flat fill in the sky or water colour, chosen by the cell's bit 6;
 *   2. one sprite into the buffer — the tile proper;
 *   3. for the hoop ids only, a second sprite pushed onto `b.s`/`b.at`/`b.W`, a deferred
 *      list that `d.n()` flushes **after** `aA.a(...)` has drawn the ball.
 *
 * So a hoop has a back half and a front half and the ball passes between them. Here that
 * is two containers: `view` (fill, hazards, back halves) and `front`, which the caller
 * adds to the stage *above* the ball.
 *
 * Two deviations, both deliberate:
 *
 * - **Every visible cell gets a background fill.** Nine of the drawer's cases skip the
 *   `fillRect` and rely on their sprite being opaque; all nine are (checked against
 *   `assets/atlas.png`), so filling underneath changes nothing — except in the corner
 *   where the original leaves stale ring-buffer pixels, where it is an improvement.
 * - **Twelve ids rotate at draw time.** `b.a(V[50|51|52|54], 3|4|5)` builds a rotated
 *   `Image` inline for ids 40-42, 44-46, 48-50 and 52-54 instead of caching it in `V`, so
 *   T2 had no `V` entry to bake into the atlas. Pixi rotates the sprite instead, which is
 *   free and keeps the atlas byte-identical. Rotations are counter-clockwise; see
 *   docs/ORIGINAL.md for how the direction was finally pinned down.
 */
import { Container, Graphics, Rectangle, Sprite, Texture, type Spritesheet } from 'pixi.js';

import type { Door } from './Door.ts';
import { DOOR_SIZE } from './Door.ts';
import { TILE_SIZE, PLATFORM_SIZE, type Level } from './Level.ts';
import { VIEW_HEIGHT, VIEW_WIDTH } from './Camera.ts';
import { DOOR_ID, HAZARD_BOX_ID, TILES, backFrame, cellColour } from './Tiles.ts';

/** `b.Q` — the 24x24 spiked wheel, built from four mirrored copies of cell (1,3). */
const HAZARD_FRAME = 'moving_platform';

/** `V[12]` — the 24x48 door strip a 24x24 window slides down. */
const DOOR_FRAME = 'door';

const QUARTER_TURN = Math.PI / 2;

export type TileMapOptions = {
  /** Supplies the door's slide offset. Without one the door renders shut. */
  door?: Door;
  /**
   * T12 — how wide a window to build, in pixels. 128 (the `FullCanvas` width) unless
   * widescreen asked for more, in which case the caller passes a camera x shifted left by
   * the same margin. Only culling changes: nothing here knows or cares that the extra
   * columns are not on the original's screen.
   */
  viewWidth?: number;
};

export class TileMap {
  /** Cell fills, hazards and the back half of every tile. Goes below the ball. */
  readonly view = new Container();

  /** The hoop halves `d.n()` flushes after the ball. Add this above the ball. */
  readonly front = new Container();

  private readonly level: Level;

  private readonly sheet: Spritesheet;

  private readonly door: Door | undefined;

  /** Width of the window to build, in pixels. `VIEW_WIDTH` unless T12 widened it. */
  private readonly viewWidth: number;

  private readonly background = new Graphics();

  private readonly hazardLayer = new Container();

  private readonly backLayer = new Container();

  private readonly hazards: Sprite[] = [];

  private readonly backPool: Sprite[] = [];

  private readonly frontPool: Sprite[] = [];

  private doorSprite: Sprite | null = null;

  private doorTexture: Texture | null = null;

  private doorOffset = -1;

  constructor(level: Level, sheet: Spritesheet, options: TileMapOptions = {}) {
    this.level = level;
    this.sheet = sheet;
    this.door = options.door;
    this.viewWidth = options.viewWidth ?? VIEW_WIDTH;

    // Fill, then hazards, then tiles: the two shipped levels whose travel box contains a
    // solid cell (3 #10 and 9 #0) need the wheel to pass *behind* that cell, which is what
    // the original's per-cell clip to the `case 10` tiles achieves.
    this.view.addChild(this.background, this.hazardLayer, this.backLayer);

    if (level.platforms.length > 0) {
      const texture = this.texture(HAZARD_FRAME);
      for (const _record of level.platforms) {
        const sprite = new Sprite(texture);
        sprite.visible = false;
        this.hazards.push(sprite);
        this.hazardLayer.addChild(sprite);
      }
    }

    const doorTile = level.tileAt(level.door.x, level.door.y);
    if (doorTile === DOOR_ID) {
      this.doorSprite = new Sprite();
      this.backLayer.addChild(this.doorSprite);
    }
  }

  /**
   * How many sprites the last `update()` left visible — pool entries in use, plus the
   * hazards and the door. T13's `perf.html` reports it beside the draw-call count,
   * because "one draw call" only means anything next to how many sprites went into it.
   */
  get spriteCount(): number {
    const pooled = (pool: Sprite[]): number => pool.reduce((n, s) => n + (s.visible ? 1 : 0), 0);
    return (
      pooled(this.backPool) +
      pooled(this.frontPool) +
      pooled(this.hazards) +
      (this.doorSprite?.visible === true ? 1 : 0)
    );
  }

  destroy(): void {
    this.doorTexture?.destroy(false);
    this.doorTexture = null;
    this.view.destroy({ children: true });
    this.front.destroy({ children: true });
  }

  /**
   * Redraw the window at `(camX, camY)`. Cheap enough to call every frame; the camera's
   * own position is integral, so nothing lands off the pixel grid.
   */
  update(camX: number, camY: number): void {
    const firstColumn = Math.floor(camX / TILE_SIZE);
    const lastColumn = Math.ceil((camX + this.viewWidth) / TILE_SIZE);
    const firstRow = Math.floor(camY / TILE_SIZE);
    const lastRow = Math.ceil((camY + VIEW_HEIGHT) / TILE_SIZE);

    this.background.clear();
    let backUsed = 0;
    let frontUsed = 0;

    for (let row = firstRow; row < lastRow; row++) {
      const screenY = row * TILE_SIZE - camY;

      // Merge horizontal runs of one colour so a screenful of sky is one rectangle
      // rather than eleven.
      let runStart = firstColumn;
      let runColour = -1;

      for (let column = firstColumn; column <= lastColumn; column++) {
        const inRun = column < lastColumn;
        const raw = inRun ? this.level.rawTileAt(column, row) : -1;
        const id = inRun ? raw & 0x3f : -1;
        const colour = inRun ? cellColour(id, this.level.isUnderwater(column, row)) : -1;

        if (colour !== runColour) {
          if (runColour >= 0 && column > runStart) {
            this.background
              .rect(
                runStart * TILE_SIZE - camX,
                screenY,
                (column - runStart) * TILE_SIZE,
                TILE_SIZE,
              )
              .fill(runColour);
          }
          runStart = column;
          runColour = colour;
        }

        if (!inRun) break;

        const spec = TILES[id];
        if (!spec) continue;

        if (id === DOOR_ID || id === HAZARD_BOX_ID) continue; // drawn whole, below.

        const frame = backFrame(id, this.level.isUnderwater(column, row));
        if (frame) {
          this.place(
            this.backPool,
            this.backLayer,
            backUsed++,
            frame,
            column,
            row,
            camX,
            camY,
          ).rotation = -(spec.turns ?? 0) * QUARTER_TURN;
        }
        if (spec.front) {
          this.place(this.frontPool, this.front, frontUsed++, spec.front, column, row, camX, camY);
        }
      }
    }

    for (let i = backUsed; i < this.backPool.length; i++) this.backPool[i]!.visible = false;
    for (let i = frontUsed; i < this.frontPool.length; i++) this.frontPool[i]!.visible = false;

    this.updateHazards(camX, camY);
    this.updateDoor(camX, camY);
  }

  private place(
    pool: Sprite[],
    layer: Container,
    index: number,
    frame: string,
    column: number,
    row: number,
    camX: number,
    camY: number,
  ): Sprite {
    let sprite = pool[index];
    if (!sprite) {
      sprite = new Sprite();
      // Anchored at the centre so the rotated ids need no offset of their own.
      sprite.anchor.set(0.5);
      pool[index] = sprite;
      layer.addChild(sprite);
    }
    sprite.texture = this.texture(frame);
    sprite.position.set(
      column * TILE_SIZE + TILE_SIZE / 2 - camX,
      row * TILE_SIZE + TILE_SIZE / 2 - camY,
    );
    sprite.rotation = 0;
    sprite.visible = true;
    return sprite;
  }

  /** `b.a(...)`'s `case 10`: the wheel wherever its record currently puts it. */
  private updateHazards(camX: number, camY: number): void {
    this.level.platforms.forEach((platform, index) => {
      const sprite = this.hazards[index];
      if (!sprite) return;
      const x = platform.x - camX;
      const y = platform.y - camY;
      sprite.position.set(x, y);
      sprite.visible =
        x > -PLATFORM_SIZE && x < this.viewWidth && y > -PLATFORM_SIZE && y < VIEW_HEIGHT;
    });
  }

  /**
   * `b.a(...)`'s `case 9` plus `b.m()`: a 24x24 window `offset` pixels down the strip.
   *
   * PLAN-HD H3.5 flagged this as one of two places that slice a texture by hand and so
   * would need the HD frame rectangle. It turns out to need nothing: `Texture.frame` is
   * in the source's *logical* units, not its texels — `Spritesheet` divides every packed
   * rectangle by `meta.scale` and stamps the same number on `textureSource.resolution` —
   * so `frame.y + offset` adds virtual pixels to virtual pixels at either density and
   * `DOOR_SIZE` stays 24. The arithmetic below is the same code for both sheets, which is
   * what the plan asked for; `tests/tilemap.test.ts` pins the invariant it rests on (both
   * atlases place the door strip on a whole-texel boundary, so the division is exact).
   */
  private updateDoor(camX: number, camY: number): void {
    const sprite = this.doorSprite;
    if (!sprite) return;

    const offset = this.door?.offset ?? 0;
    if (offset !== this.doorOffset) {
      this.doorOffset = offset;
      const source = this.texture(DOOR_FRAME);
      const previous = this.doorTexture;
      this.doorTexture = new Texture({
        source: source.source,
        frame: new Rectangle(source.frame.x, source.frame.y + offset, DOOR_SIZE, DOOR_SIZE),
      });
      sprite.texture = this.doorTexture;
      previous?.destroy(false);
    }

    const x = this.level.door.x * TILE_SIZE - camX;
    const y = this.level.door.y * TILE_SIZE - camY;
    sprite.position.set(x, y);
    sprite.visible = x > -DOOR_SIZE && x < this.viewWidth && y > -DOOR_SIZE && y < VIEW_HEIGHT;
  }

  private texture(frame: string): Texture {
    const texture = this.sheet.textures[frame];
    if (!texture) throw new Error(`atlas frame "${frame}" is missing`);
    return texture;
  }
}
