/**
 * T7 — the camera, distilled out of the MIDlet's scroll bookkeeping.
 *
 * The original has no camera object. It has a 156x96 offscreen `Image` (`b.H`) used as a
 * **horizontal ring buffer** of 13 tile columns, and four ints that index it:
 *
 * | field | meaning |
 * | --- | --- |
 * | `b.n` / `b.m` | tile column/row the buffer's contents start at |
 * | `b.I` | buffer x of the screen's left edge; `d.n()` blits `H` at `-I`, twice when it wraps |
 * | `b.i` | buffer x of the screen's right edge — always `I + 128` mod 156 |
 * | `b.ag` | write cursor: the buffer column `b.b()` refills next as the view scrolls |
 * | `b.ai` | is the camera currently following the ball |
 * | `b.ar` | buffer x the ball must reach for following to start again |
 *
 * None of that survives the port: Pixi redraws the visible tiles every frame from the
 * tilemap, so there is nothing to scroll incrementally and no wrap to track. What has to
 * survive is the *behaviour* the bookkeeping produced, and it is simpler than it looks:
 *
 * - **Horizontally** the ball is pinned at screen x 64 once it gets there, and the camera
 *   stops dead at either end of the level. Every `ar` the original computes works out to
 *   screen x 64 — at the left edge `ar = i - 64` with `i = I + 128`, at the right
 *   `ar = (I + 64) % 156` — so one constant covers both.
 * - **Vertically** there is no scrolling at all: `d.e()` jumps the view by exactly seven
 *   rows (84px) the moment the ball leaves the 96px play area, and `d.a(...)` starts a
 *   level on the row band `floor(spawnTileY / 7) * 7`.
 *
 * Two details are the original's and are kept deliberately:
 *
 * - a level entered away from either end starts with the camera at
 *   `floor(ballX / 12) * 12 - 57`, so the ball sits at screen x 57..68 rather than exactly
 *   64, and only latches on once it crosses 64;
 * - the vertical band is **not** clamped to the level. `d.e()` would happily scroll past
 *   the last row; the maps' geometry is what stops the ball getting there.
 */
import type { Level } from './Level.ts';
import { TILE_SIZE } from './Level.ts';

/** Visible width, i.e. the `FullCanvas` width. `d.n()` blits 128 of the buffer's 156px. */
export const VIEW_WIDTH = 128;

/** Visible height of the play area: `b.H` is 96 tall, the rest of the screen is HUD. */
export const VIEW_HEIGHT = 96;

/** Screen x the ball is held at while the camera follows. */
export const SCROLL_ANCHOR_X = 64;

/**
 * `c(int,int)`'s `n < this.ar + 10` / `n > this.ar - 10`: following only latches on if the
 * ball is *within ten pixels* past the anchor. A single tick can move the ball up to 15px
 * (`|e.l| <= 150`, stepped one pixel per unit of ten), so the window can in principle be
 * jumped over — the next tick catches it, because the ball cannot then leave the window in
 * the same direction without the camera moving.
 */
export const SCROLL_LATCH_WINDOW = 10;

/** `d.e()`'s `m += 7` / `m -= 7`: the vertical view moves a band at a time. */
export const ROWS_PER_BAND = 7;

/** 84px — `d.e()`'s `aA.A += 84`, the pixel height of one band. */
export const BAND_HEIGHT = ROWS_PER_BAND * TILE_SIZE;

export class Camera {
  /** Pixel column of the screen's left edge, in level space. */
  x = 0;

  /** Pixel row of the play area's top edge, in level space. */
  y = 0;

  /** `b.ai` — true while the camera tracks the ball one-for-one. */
  following = false;

  /**
   * Which end of the level is holding the view still, or null while it follows.
   *
   * `b.c(int,int)` gates its two latch tests on which columns the ring buffer holds —
   * `n - (13 - ag / 12) <= 0` is "column 0 is loaded" and `n + ag / 12 >= d` is "the last
   * column is loaded" — not on the view's pixel position. The port needs the distinction
   * because the stop below leaves the view a pixel or two inside the edge, so "x === 0"
   * is not the same question as "the left end is where we ran out".
   */
  private blockedEnd: 'left' | 'right' | null = null;

  private maxX = 0;

  /** Rightmost camera x for a level: `(width - 13) * 12 + 28`, i.e. `pixelWidth - 128`. */
  static maxXFor(level: Level): number {
    return Math.max(0, level.pixelWidth - VIEW_WIDTH);
  }

  /**
   * `d.a(int x, int y, int size, int, int)` — place the camera for a ball about to be
   * spawned at level pixel `(ballX, ballY)`.
   */
  reset(level: Level, ballX: number, ballY: number): void {
    this.maxX = Camera.maxXFor(level);

    if (ballX < SCROLL_ANCHOR_X) {
      // `n < 64`: hard against the left edge, waiting for the ball to reach the anchor.
      this.x = 0;
      this.following = false;
      this.blockedEnd = 'left';
    } else if (ballX > level.pixelWidth - SCROLL_ANCHOR_X) {
      // `n > d * 12 - 64`: hard against the right edge.
      this.x = this.maxX;
      this.following = false;
      this.blockedEnd = 'right';
    } else {
      // `n = n6 - 6; I = 15` — the view starts on a tile boundary six columns left of the
      // ball's, which is 57px rather than 64. The offset is the original's; keep it.
      this.x = Math.floor(ballX / TILE_SIZE) * TILE_SIZE - 57;
      this.following = true;
      this.blockedEnd = null;
    }

    this.y = Math.floor(ballY / TILE_SIZE / ROWS_PER_BAND) * BAND_HEIGHT;
  }

  /** Screen x of a level pixel. */
  toScreenX(levelX: number): number {
    return levelX - this.x;
  }

  /** Screen y of a level pixel. Negative or past 96 means the ball has left the band. */
  toScreenY(levelY: number): number {
    return levelY - this.y;
  }

  /**
   * `b.c(int,int)` then `b.b(int,int,int)`: latch on when the ball reaches the anchor
   * heading out of the level's end, then track it, then stop dead at the far end.
   *
   * `deltaX` is `e.p`, the ball's movement this tick (`p = r - n3`).
   */
  follow(ballX: number, deltaX: number): void {
    // `b.c(int,int)`'s parameter `n2` starts as the tick's movement and is *reassigned*
    // to `n - ar` by whichever latch fires, so the tick that latches moves the view by
    // the whole distance the ball is past the anchor rather than by its own delta. That
    // is what pins the ball to screen x 64 exactly; T11 found the port a pixel adrift
    // on level 001 at tick 97 because it applied the delta on that tick too.
    let step = deltaX;
    if (!this.following) {
      const screenX = this.toScreenX(ballX);
      if (
        (this.blockedEnd === 'left' &&
          screenX >= SCROLL_ANCHOR_X &&
          screenX < SCROLL_ANCHOR_X + SCROLL_LATCH_WINDOW) ||
        (this.blockedEnd === 'right' &&
          screenX <= SCROLL_ANCHOR_X &&
          screenX > SCROLL_ANCHOR_X - SCROLL_LATCH_WINDOW)
      ) {
        this.following = true;
        this.blockedEnd = null;
        step = screenX - SCROLL_ANCHOR_X;
      }
    }

    if (!this.following) return;

    // `b.b(int,int,int)`'s two "no more columns that way" branches **undo** the tick's
    // move (`I -= n2; i -= n2`) and clear `ai`; they do not clamp. So the view stops on
    // the last position that fitted, which is up to a tick's movement short of the
    // level's edge and stays there — and the ball keeps going, which is what puts it
    // past screen x 64 in the first place. T11 found the difference on levels 004-011:
    // clamping left the camera one or two pixels further out than the original's.
    const next = this.x + step;
    if (next < 0) {
      this.following = false;
      this.blockedEnd = 'left';
      return;
    }
    if (next > this.maxX) {
      this.following = false;
      this.blockedEnd = 'right';
      return;
    }
    this.x = next;
  }

  /**
   * `d.a()`'s `if (aA.A < 0 || aA.A > 96) this.e()`, and `d.e()`'s band step. Returns the
   * pixel shift applied to the view, or zero if the ball is still inside the band.
   *
   * The ball needs **no** correction for it, which T8 settled: `d.e()` moves `b.m` by
   * seven rows and `aA.A` by 84 pixels in opposite directions precisely so that
   * `A + m * 12` — the ball's world y — comes out unchanged, and a port that keeps the
   * ball in world pixels gets that for free. The return value is for a caller that wants
   * to know a band boundary was crossed. See `src/game/Playfield.ts`.
   *
   * What T8 missed, and T11's trace of level 006 found at tick 16, is that `d.e()` also
   * **re-bases the view horizontally**. It rebuilds the ring buffer from scratch around
   * the ball's current column, and the three branches it picks between work out, in world
   * pixels, to:
   *
   * - following (`ai`): `I = 14 + n2`, `n = n + r / 12 - 6` and `aA.r = 78 + n2` — which
   *   reduces to `x = ballX - 64`, i.e. the ball is snapped **onto** the anchor. The two
   *   clamps on `n` inside that branch move a column count and the ball's buffer x by
   *   equal and opposite amounts, so they do not change the world position at all — the
   *   view really can end up outside `[0, maxX]` here, and that is the original's.
   * - stopped at the left end: `n = 0; I = 0` — exactly `x = 0`.
   * - stopped at the right end: `n = d - 13; I = 28` — exactly `x = maxX`.
   *
   * So a band scroll is also the one thing that un-does the pixel or two the stop above
   * leaves the view short of an edge.
   */
  followVertical(ballX: number, ballY: number): number {
    const screenY = this.toScreenY(ballY);
    if (screenY >= 0 && screenY <= VIEW_HEIGHT) return 0;

    const shift = screenY < 0 ? -BAND_HEIGHT : BAND_HEIGHT;
    this.y += shift;

    if (this.following) this.x = ballX - SCROLL_ANCHOR_X;
    else if (this.blockedEnd === 'right') this.x = this.maxX;
    else if (this.blockedEnd === 'left') this.x = 0;

    return shift;
  }
}
